1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.ArrayList;
7	import java.util.List;
8	import java.util.Locale;
9	
10	import org.springframework.samples.petclinic.model.Owner;
11	import org.springframework.samples.petclinic.repository.OwnerRepository;
12	
13	/**
14	 * Single source of truth for household identity. A household groups owners that share the same last
15	 * name and the same postcode, with the last name compared case-insensitively and with surrounding and
16	 * internal whitespace collapsed (so "Smith" / " smith " belong together).
17	 *
18	 * <p>The {@link #id(String, String)} derived from that normalized (lastName, postcode) pair is
19	 * deterministic: the same last name and postcode always map to the same value, so every owner at the
20	 * same household receives an identical {@code householdId} automatically — it is no longer something an
21	 * owner "joins" via {@code sharesHousehold}. The household is therefore the basis for duplicate
22	 * detection ({@link CheckHouseholdUnique}): two owners belong to the same household exactly when their
23	 * ids are equal.
24	 */
25	final class Household {
26	
27	    private Household() {
28	    }
29	
30	    /** Lower-case (locale-independent) with leading/trailing and repeated internal whitespace collapsed. */
31	    private static String normalize(String value) {
32	        if (value == null) {
33	            return "";
34	        }
35	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
36	    }
37	
38	    /**
39	     * The canonical household key for a (lastName, postcode) pair — the single definition of household
40	     * membership: {@code normalizedLastName + "|" + postcode}. Two owners belong to the same household
41	     * exactly when their keys are equal; {@link #id} hashes this same key, so the duplicate check and the
42	     * assigned id can never diverge. The last name is normalized (whitespace collapsed, lower-cased); the
43	     * postcode is trimmed and used as given (a {@code null} or blank postcode contributes an empty
44	     * component).
45	     */
46	    static String key(String lastName, String postcode) {
47	        String pc = (postcode == null) ? "" : postcode.trim();
48	        return normalize(lastName) + "|" + pc;
49	    }
50	
51	    /**
52	     * All existing owners that belong to the household of the given last name and postcode — those whose
53	     * own (recomputed) {@link #id household id} equals this household's. The single definition of
54	     * "collect the members of a household", shared by the callers that count members and that cap a new
55	     * member's level; soft-deleted owners are included (callers that must exclude them filter the result).
56	     */
57	    static List<Owner> membersOf(String lastName, String postcode, OwnerRepository repository) {
58	        String householdId = id(lastName, postcode);
59	        List<Owner> members = new ArrayList<>();
60	        for (Owner existing : repository.findAll()) {
61	            if (householdId.equals(id(existing.getLastName(), existing.getPostcode()))) {
62	                members.add(existing);
63	            }
64	        }
65	        return members;
66	    }
67	
68	    /**
69	     * Deterministic household identifier for the given last name and postcode: {@code "H-"} followed by
70	     * the first 12 hex characters of the SHA-256 of the {@link #key household key}.
71	     */
72	    static String id(String lastName, String postcode) {
73	        String key = key(lastName, postcode);
74	        try {
75	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
76	            StringBuilder sb = new StringBuilder("H-");
77	            for (int i = 0; i < 6; i++) {
78	                sb.append(String.format("%02x", digest[i]));
79	            }
80	            return sb.toString();
81	        }
82	        catch (NoSuchAlgorithmException e) {
83	            throw new IllegalStateException("SHA-256 not available", e);
84	        }
85	    }
86	}
