3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	
6	/**
7	 * Assigns the owner's {@code householdId} — a deterministic identifier derived from the normalized last
8	 * name and the postcode (see {@link Household}). Because the derivation is deterministic, every owner
9	 * with the same last name and postcode receives the same value, which is then persisted and returned;
10	 * an owner admitted to an existing household via {@code sharesHousehold} simply computes the same id.
11	 */
12	public class AssignHousehold {
13	
14	    public void service(@Val Owner owner) {
15	        owner.setHouseholdId(Household.id(owner.getLastName(), owner.getPostcode()));
16	    }
17	}
