1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	
6	/**
7	 * Ensures this owner's {@code possibleDuplicate} / {@code possibleDuplicateOf} response fields are set,
8	 * on both the create and read pipelines.
9	 *
10	 * <p>A possible duplicate was a soft near match: another owner sharing this owner's last name
11	 * (case-insensitively) and postcode. Now that the household is keyed on exactly (lastName, postcode)
12	 * (see {@link Household}), any such owner is in the <em>same household</em> and could only have been
13	 * created by declaring {@code sharesHousehold} to bypass the household duplicate block
14	 * ({@link CheckHouseholdUnique}) — a non-declared one is rejected with a 409. A declared household member
15	 * is not a suspected duplicate, so there is no longer any near match that should be flagged: the fields
16	 * are therefore always {@code false} / {@code null}. They are computed per request, not persisted, and
17	 * recomputed identically on each read.
18	 */
19	public class FlagPossibleDuplicate {
20	
21	    public void service(@Val Owner owner) {
22	        owner.setPossibleDuplicate(false);
23	        owner.setPossibleDuplicateOf(null);
24	    }
25	}
