1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.List;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	
9	/**
10	 * Caps the new owner's {@link Owner#getMembershipLevel() membershipLevel} at one above the current
11	 * maximum membershipLevel among their existing household members (see
12	 * {@link Household#membersOf(String, String, OwnerRepository)}). The cap is persisted on the owner (see
13	 * {@link Owner#getMembershipLevelCap()}) so the ceiling is honoured on later reads.
14	 *
15	 * <p>Runs before {@link SaveOwner}, so the owner being created is not yet among the household members and
16	 * does not cap itself. With no existing household member, no cap is applied.
17	 */
18	public class CapMembershipLevel {
19	
20	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
21	        List<Owner> members = Household.membersOf(owner.getLastName(), owner.getPostcode(), ownerRepository);
22	        if (members.isEmpty()) {
23	            return; // no existing household member -> no cap
24	        }
25	        // Each member's level is read for the current household size (the members seen here, before this
26	        // owner is saved); read-only, so no member's transient state is mutated.
27	        int maxLevel = 0;
28	        for (Owner member : members) {
29	            maxLevel = Math.max(maxLevel, member.membershipLevelForHouseholdSize(members.size()));
30	        }
31	        owner.setMembershipLevelCap(maxLevel + 1);
32	    }
33	}
