1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Computes this owner's {@code householdSize} — the number of owners that belong to the same household,
9	 * i.e. that share the same deterministic {@link Household#id(String, String) household id} (same last
10	 * name and postcode), including this owner. Used by {@link Owner#getMembershipPoints()} to award points
11	 * for a household of three or more. Computed per request and mutated onto the owner in place, not
12	 * persisted, because household membership changes as owners are created and removed; it is recomputed
13	 * identically on each read.
14	 */
15	public class CountHouseholdMembers {
16	
17	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
18	        owner.setHouseholdSize(
19	            Household.membersOf(owner.getLastName(), owner.getPostcode(), ownerRepository).size());
20	    }
21	}
