28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "address_line1")
44	    private String addressLine1;
45	
46	    @Column(name = "address_line2")
47	    private String addressLine2;
48	
49	    @Column(name = "city")
50	    @NotEmpty
51	    private String city;
52	
53	    @Column(name = "postcode")
54	    private String postcode;
55	
56	    @Column(name = "telephone")
57	    @NotEmpty
58	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (+ then 8 to 15 digits)")
59	    private String telephone;
60	
61	    @Column(name = "email")
62	    private String email;
63	
64	    @Column(name = "title")
65	    private String title;
66	
67	    @Column(name = "registration_date")
68	    private LocalDate registrationDate;
69	
70	    @Column(name = "birth_date")
71	    private LocalDate birthDate;
72	
73	    @Column(name = "customer_code")
74	    private String customerCode;
75	
76	    @Column(name = "membership_number")
77	    private String membershipNumber;
78	
79	    @Column(name = "household_id")
80	    private String householdId;
81	
82	    @Column(name = "namesake_count")
83	    private Integer namesakeCount;
84	
85	    @Column(name = "membership_level_cap")
86	    private Integer membershipLevelCap;
87	
88	    @Column(name = "deleted")
89	    private boolean deleted;
90	
91	    @Transient
92	    private Integer householdSize;
93	
94	    @Transient
95	    private Boolean bulkSignupWarning;
96	
97	    @Transient
98	    private Boolean possibleDuplicate;
99	
100	    @Transient
101	    private Integer possibleDuplicateOf;
102	
103	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
104	    private Set<Pet> pets;
105	
106	    public String getAddress() {
107	        return this.address;
108	    }
109	
110	    public void setAddress(String address) {
111	        this.address = address;
112	    }
113	
114	    /**
115	     * The first line of the structured postal address (street number and name), or {@code null} when
116	     * the owner was supplied with only the flat {@link #getAddress() address}. The preferred street
117	     * address when present; {@link #getAddress() address} holds the composed form.
118	     */
119	    public String getAddressLine1() {
120	        return this.addressLine1;
121	    }
122	
123	    public void setAddressLine1(String addressLine1) {
124	        this.addressLine1 = addressLine1;
125	    }
126	
127	    /**
128	     * The optional second line of the structured postal address (unit, suite, etc.), or {@code null}
129	     * when none was supplied. When present it is appended to the composed {@link #getAddress() address}.
130	     */
131	    public String getAddressLine2() {
132	        return this.addressLine2;
133	    }
134	
135	    public void setAddressLine2(String addressLine2) {
136	        this.addressLine2 = addressLine2;
137	    }
138	
139	    public String getCity() {
140	        return this.city;
141	    }
142	
143	    public void setCity(String city) {
144	        this.city = city;
145	    }
146	
147	    public String getPostcode() {
148	        return this.postcode;
149	    }
150	
151	    public void setPostcode(String postcode) {
152	        this.postcode = postcode;
153	    }
154	
155	    public String getTelephone() {
156	        return this.telephone;
157	    }
158	
159	    public void setTelephone(String telephone) {
160	        this.telephone = telephone;
161	    }
162	
163	    /**
164	     * The stored {@link #getTelephone() telephone} formatted for humans by {@link TelephoneFormatter}:
165	     * the country code, a space, then the national digits grouped in threes (e.g. {@code +61412345678}
166	     * -> {@code +61 412 345 678}). The raw {@link #getTelephone() telephone} stays in E.164 form.
167	     */
168	    public String getTelephoneDisplay() {
169	        return TelephoneFormatter.toDisplay(this.telephone);
170	    }
171	
172	    public String getEmail() {
173	        return this.email;
174	    }
175	
176	    public void setEmail(String email) {
177	        this.email = email;
178	    }
179	
180	    public String getTitle() {
181	        return this.title;
182	    }
183	
184	    public void setTitle(String title) {
185	        this.title = title;
186	    }
187	
188	    /**
189	     * The owner's salutation: the {@link #getTitle() title} followed by a single space and the
190	     * {@link #getLastName() last name} (e.g. {@code "DR Franklin"}), or just the last name when no
191	     * title was supplied. Derived per response, not persisted.
192	     */
193	    public String getSalutation() {
194	        if (this.title == null || this.title.isBlank()) {
195	            return this.getLastName();
196	        }
197	        return this.title + " " + this.getLastName();
198	    }
199	
200	    public LocalDate getRegistrationDate() {
201	        return this.registrationDate;
202	    }
203	
204	    public void setRegistrationDate(LocalDate registrationDate) {
205	        this.registrationDate = registrationDate;
206	    }
207	
208	    /**
209	     * The fiscal year a {@code date} belongs to, as a four-digit year. The fiscal year starts on 1 July
210	     * and is identified by the calendar year in which it ends: a date on or after 1 July of year
211	     * {@code Y} belongs to the fiscal year ending in {@code Y + 1}, while a date in January to June of
