389	    /** The membership points this owner would score for the given household size; see
390	     * {@link #getMembershipPoints()}. Read-only, so a level can be derived for a hypothetical household
391	     * size without mutating this owner's transient {@link #setHouseholdSize(Integer) householdSize}. */
392	    private int membershipPoints(Integer householdSize) {
393	        int points = 0;
394	        boolean hasEmail = this.email != null && !this.email.isBlank();
395	        if (hasEmail) {
396	            points += 2;
397	        }
398	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
399	        if (unique) {
400	            points += 1;
401	        }
402	        boolean largeHousehold = householdSize != null && householdSize >= 3;
403	        if (largeHousehold) {
404	            points += 2;
405	        }
406	        boolean tenured = this.registrationDate != null
407	            && fiscalYear(LocalDate.now()) - fiscalYear(this.registrationDate) >= 1;
408	        if (tenured) {
409	            points += 3;
410	        }
411	        return points;
412	    }
