414	    /**
415	     * The owner's membership level, derived from {@link #getMembershipPoints() membershipPoints}:
416	     * 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more. When a
417	     * {@link #getMembershipLevelCap() membershipLevelCap} applies, the derived level is capped to it, so
418	     * a new owner cannot exceed one above the maximum level among their household members.
419	     */
420	    public int getMembershipLevel() {
421	        return membershipLevelForHouseholdSize(this.householdSize);
422	    }
