424	    /**
425	     * This owner's membership level as it would be derived for the given household size — i.e. the value
426	     * this owner's own {@code GET} would report when its household holds {@code householdSize} members —
427	     * after applying any {@link #getMembershipLevelCap() cap}. Read-only: used to size a new household
428	     * member's cap from the existing members' levels without mutating their transient household size.
429	     */
430	    public int membershipLevelForHouseholdSize(Integer householdSize) {
431	        int points = membershipPoints(householdSize);
432	        int level;
433	        if (points <= 1) {
434	            level = 1;
435	        }
436	        else if (points <= 3) {
437	            level = 2;
438	        }
439	        else if (points <= 5) {
440	            level = 3;
441	        }
442	        else {
443	            level = 4;
444	        }
445	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
446	            return this.membershipLevelCap;
447	        }
448	        return level;
449	    }
