471	     * (NSW -> Australia/Sydney, VIC -> Australia/Melbourne, QLD -> Australia/Brisbane). The single
472	     * source of truth for the timezone derivation read by {@link #getTimezone()}.
473	     */
474	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
475	        "NSW", "Australia/Sydney",
476	        "VIC", "Australia/Melbourne",
477	        "QLD", "Australia/Brisbane");
