501	     * The canonical region whose postcode band contains {@code postcode} (NSW 2000-2099, VIC 3000-3099,
502	     * QLD 4000-4099), or {@code null} when {@code postcode} is absent, not four digits, or in no known
503	     * range.
504	     */
505	    public static String regionOfPostcode(String postcode) {
506	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
507	            return null;
508	        }
509	        int value = Integer.parseInt(postcode);
510	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
511	            int[] range = entry.getValue();
512	            if (value >= range[0] && value <= range[1]) {
513	                return entry.getKey();
514	            }
515	        }
516	        return null;
517	    }
