534	    /**
535	     * The owner's IANA timezone, derived from the {@link #getLocality() locality}/region via the fixed
536	     * region-to-timezone table (NSW -> Australia/Sydney, VIC -> Australia/Melbourne,
537	     * QLD -> Australia/Brisbane), or {@code null} (so the field is absent from the response) when the
538	     * locality maps to no known region.
539	     */
540	    public String getTimezone() {
541	        return REGION_TIMEZONE.get(getLocality());
542	    }
