544	    /**
545	     * The single Luhn check digit (0-9) computed over the digits contained in the
546	     * {@link #getCustomerCode() customerCode}: non-digit characters are ignored, each second digit from
547	     * the right is doubled (subtracting 9 when the double exceeds 9), the results are summed, and the
548	     * check digit is {@code (10 - sum % 10) % 10}. {@code 0} when no customer code is assigned.
549	     */
550	    public int getCheckDigit() {
551	        String code = this.customerCode;
552	        if (code == null) {
553	            return 0;
554	        }
555	        int sum = 0;
556	        boolean dbl = true;
557	        for (int i = code.length() - 1; i >= 0; i--) {
558	            char c = code.charAt(i);
559	            if (c < '0' || c > '9') {
560	                continue;
561	            }
562	            int d = c - '0';
563	            if (dbl) {
564	                d *= 2;
565	                if (d > 9) {
566	                    d -= 9;
567	                }
568	            }
569	            sum += d;
570	            dbl = !dbl;
571	        }
572	        return (10 - (sum % 10)) % 10;
573	    }
