14	/**
15	 * Assigns the {@code customerCode} formatted {@code <REGION>-<HASH8>}, the single region-and-hash owner
16	 * identity. REGION is the region code derived from the owner's {@link Owner#getPostcode() postcode} via
17	 * {@link Owner#regionOfPostcode(String)} (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), or
18	 * {@code "UNKNOWN"} when the postcode is absent or in no known range. HASH8 is the first 8 upper-case
19	 * hex characters of the SHA-256 of the owner's {@link OwnerTelephone normalized (E.164) telephone}
20	 * concatenated with the last name.
21	 *
22	 * <p>The region-and-hash value would otherwise collide for two owners with the same normalized
23	 * telephone and last name in the same region. When the computed value matches an existing owner's
24	 * {@code customerCode}, it is de-duplicated by appending {@code -<n>} with the smallest {@code n} of 2
25	 * or more that makes it unique. Every value built from the customer code — the
26	 * {@link AssignMembershipNumber membership number} and its {@link Owner#getCheckDigit() check digit},
27	 * the {@link AuditOwnerCreated create audit record} and the {@link Owner#getLocality() locality} — reads
28	 * this de-duplicated value.
29	 */
30	public class AssignCustomerCode {
31	
32	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
33	        String region = Owner.regionOfPostcode(owner.getPostcode());
34	        if (region == null) {
35	            region = "UNKNOWN";
36	        }
37	        String normalizedTelephone = OwnerTelephone.toE164(owner.getTelephone());
38	        if (normalizedTelephone == null) {
39	            normalizedTelephone = owner.getTelephone() == null ? "" : owner.getTelephone();
40	        }
41	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
42	        String base = region + "-" + hash8(normalizedTelephone + lastName);
43	
44	        Set<String> existingCodes = new HashSet<>();
45	        for (Owner existing : ownerRepository.findAll()) {
46	            if (existing.getCustomerCode() != null) {
47	                existingCodes.add(existing.getCustomerCode());
48	            }
49	        }
50	
51	        String customerCode = base;
52	        for (int n = 2; existingCodes.contains(customerCode); n++) {
53	            customerCode = base + "-" + n;
54	        }
55	        owner.setCustomerCode(customerCode);
56	    }
57	
58	    /** First 8 upper-case hex characters of the SHA-256 of {@code value}'s UTF-8 bytes. */
59	    private static String hash8(String value) {
60	        try {
61	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
62	            StringBuilder sb = new StringBuilder(8);
63	            for (int i = 0; i < 4; i++) {
64	                sb.append(String.format("%02X", digest[i]));
65	            }
66	            return sb.toString().toUpperCase(Locale.ROOT);
67	        }
68	        catch (NoSuchAlgorithmException e) {
69	            throw new IllegalStateException("SHA-256 not available", e);
70	        }
71	    }
72	}
