2	
3	import java.util.regex.Pattern;
4	
5	import org.springframework.samples.petclinic.model.TelephoneFormatter;
6	
7	/**
8	 * Single source of truth for what a "normalized" owner telephone is: the E.164 form.
9	 * {@link ValidateNewOwner} enforces the rule and stores the E.164 value through here, so the stored and
10	 * returned telephone (and the owner's derived identity key, which includes it) share one canonical form.
11	 *
12	 * <p>Normalization strips spaces, dashes and brackets, then forms the canonical E.164 string:
13	 * <ul>
14	 *   <li>a leading {@code '+'} and country code are kept as-is;</li>
15	 *   <li>otherwise country code {@code +61} is assumed and a single leading {@code '0'} is dropped from
16	 *       the national digits.</li>
17	 * </ul>
18	 * The result must be a {@code '+'} followed by 8 to 15 digits. On top of that general rule, the
19	 * national-number length (the digits after the country code) must match the country code when it is one
20	 * we recognize: {@code +61} requires 9 national digits and {@code +1} requires 10 (see
21	 * {@link TelephoneFormatter#hasValidNationalLength(String)}). Anything else — non-digit leftovers, a
22	 * total digit count outside 8 to 15,
23	 * or a national-number length that is wrong for a recognized country code — is not valid E.164 and
24	 * yields {@code null}. A country code that is not in the table is accepted on the general rule alone.
25	 */
26	final class OwnerTelephone {
27	
28	    /** A valid E.164 value: '+' then 8 to 15 digits. */
29	    private static final Pattern E164 = Pattern.compile("^\\+[0-9]{8,15}$");
30	
31	    /** Characters removed before interpreting the number: spaces, dashes and brackets. */
32	    private static final Pattern SEPARATORS = Pattern.compile("[\\s\\-()]");
33	
34	    private OwnerTelephone() {
35	    }
36	
37	    /**
38	     * Returns the E.164 form of {@code telephone}, or {@code null} when it cannot form valid E.164.
39	     */
40	    static String toE164(String telephone) {
41	        if (telephone == null) {
42	            return null;
43	        }
44	        String cleaned = SEPARATORS.matcher(telephone).replaceAll("");
45	        String digits;
46	        if (cleaned.startsWith("+")) {
47	            // Keep the explicit country code; the '+' is re-added below.
48	            digits = cleaned.substring(1);
49	        }
50	        else {
51	            // No country code: assume +61 and drop a single leading '0' from the national digits.
52	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
53	            digits = "61" + national;
54	        }
55	        String e164 = "+" + digits;
56	        if (!E164.matcher(e164).matches()) {
57	            return null;
58	        }
59	        return TelephoneFormatter.hasValidNationalLength(digits) ? e164 : null;
60	    }
61	}
