2	
3	import java.util.Locale;
4	import java.util.Map;
5	
6	/**
7	 * Single source of truth for what a "normalized" owner address is. Both {@link ValidateNewOwner}
8	 * (which enforces the rule and stores the normalized value) and {@link Household} (which compares
9	 * addresses for duplicate detection and the shared household id) normalize through here, so the
10	 * duplicate check, the stored/returned value and the household id can never drift apart.
11	 *
12	 * <p>Normalization:
13	 * <ul>
14	 *   <li>trims and collapses runs of whitespace to a single space;</li>
15	 *   <li>upper-cases (locale-independent);</li>
16	 *   <li>expands common abbreviations as whole words: {@code ST -> STREET}, {@code RD -> ROAD},
17	 *       {@code AVE -> AVENUE}.</li>
18	 * </ul>
19	 * A {@code null} or all-whitespace input normalizes to the empty string, which callers treat as a
20	 * blank (and therefore missing) address.
21	 */
22	final class OwnerAddress {
23	
24	    /** Whole-word abbreviations expanded during normalization (keys are already upper-cased). */
25	    private static final Map<String, String> ABBREVIATIONS = Map.of(
26	            "ST", "STREET",
27	            "RD", "ROAD",
28	            "AVE", "AVENUE");
29	
30	    private OwnerAddress() {
31	    }
32	
33	    /**
34	     * The canonical stored form of a single structured address line: the {@link #normalize(String)
35	     * normalized} value, or {@code null} when it is absent/blank. This is the one place the
36	     * "blank line is stored as null" policy lives, so both the create ({@link ValidateNewOwner}) and
37	     * update ({@link ApplyOwner}) paths canonicalize a line identically.
38	     */
39	    static String normalizeToNull(String line) {
40	        String normalized = normalize(line);
41	        return normalized.isEmpty() ? null : normalized;
42	    }
43	
44	    /**
45	     * Composes the returned/stored address from the two normalized structured lines: the normalized
46	     * {@code line1} with the normalized {@code line2} appended after a single space when {@code line2}
47	     * is present (non-blank). Inputs are normalized through {@link #normalize(String)} first, so callers
48	     * may pass the raw request values. Returns the empty string when {@code line1} is blank.
49	     */
50	    private static String compose(String line1, String line2) {
51	        String l1 = normalize(line1);
52	        String l2 = normalize(line2);
53	        if (l1.isEmpty()) {
54	            return "";
55	        }
56	        return l2.isEmpty() ? l1 : l1 + " " + l2;
57	    }
58	
59	    /**
60	     * The effective, normalized address for an owner, preferring the structured form: the
61	     * {@link #compose(String, String) composed} structured lines when {@code line1} is present,
62	     * otherwise the normalized flat {@code address}. The single source of truth for what the stored and
63	     * returned {@code address} is and for the "address supplied in either form" validity rule — the
64	     * empty string means no address was supplied in either form.
65	     */
66	    static String effective(String line1, String line2, String address) {
67	        String composed = compose(line1, line2);
68	        return composed.isEmpty() ? normalize(address) : composed;
69	    }
70	
71	    /**
72	     * Returns the normalized form of {@code address}, or the empty string when it is {@code null} or
73	     * blank after trimming.
74	     */
75	    static String normalize(String address) {
76	        if (address == null) {
77	            return "";
78	        }
79	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
80	        if (collapsed.isEmpty()) {
81	            return "";
82	        }
83	        String[] tokens = collapsed.split(" ");
84	        StringBuilder sb = new StringBuilder(collapsed.length());
85	        for (int i = 0; i < tokens.length; i++) {
86	            if (i > 0) {
87	                sb.append(' ');
88	            }
89	            sb.append(ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
90	        }
91	        return sb.toString();
92	    }
93	}
