3	/**
4	 * Thrown when a request to create an owner resolves to the same {@code householdId} (derived from the
5	 * normalized last name and the postcode) as an existing owner — i.e. the two owners are the same
6	 * household. Carries the offending household id so {@link HouseholdDuplicateExceptionHandler} can report
7	 * it. Setting {@code sharesHousehold} on the request bypasses this block (the owner is admitted as a
8	 * declared household member). Checked so it appears in the function's {@code throws} clause and is routed
9	 * as an escalation (a 409 Conflict).
10	 */
11	public class HouseholdDuplicateException extends Exception {
12	
13	    private final String householdId;
14	
