414	    /**
415	     * The owner's membership level, derived from {@link #getMembershipPoints() membershipPoints}:
416	     * 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more. When a
417	     * {@link #getMembershipLevelCap() membershipLevelCap} applies, the derived level is capped to it, so
418	     * a new owner cannot exceed one above the maximum level among their household members.
419	     */
420	    public int getMembershipLevel() {
421	        return membershipLevelForHouseholdSize(this.householdSize);
422	    }
423	
424	    /**
425	     * This owner's membership level as it would be derived for the given household size — i.e. the value
426	     * this owner's own {@code GET} would report when its household holds {@code householdSize} members —
427	     * after applying any {@link #getMembershipLevelCap() cap}. Read-only: used to size a new household
428	     * member's cap from the existing members' levels without mutating their transient household size.
429	     */
430	    public int membershipLevelForHouseholdSize(Integer householdSize) {
431	        int points = membershipPoints(householdSize);
432	        int level;
433	        if (points <= 1) {
434	            level = 1;
435	        }
436	        else if (points <= 3) {
437	            level = 2;
438	        }
439	        else if (points <= 5) {
440	            level = 3;
441	        }
442	        else {
443	            level = 4;
444	        }
445	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
446	            return this.membershipLevelCap;
447	        }
448	        return level;
449	    }
450	
451	    /**
452	     * Fixed city-to-region table mapping each known city to its canonical region string.
453	     */
454	    private static final Map<String, String> CITY_REGION = Map.of(
455	        "Sydney", "NSW",
456	        "Melbourne", "VIC",
457	        "Brisbane", "QLD");
458	
459	    /**
460	     * Region -> inclusive {low, high} four-digit postcode range: the single canonical home of the
461	     * postcode bands (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), read via
462	     * {@link #postcodeRangeOf(String)} by both locality derivation and the create-time range check.
463	     */
464	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
465	        "NSW", new int[] {2000, 2099},
466	        "VIC", new int[] {3000, 3099},
467	        "QLD", new int[] {4000, 4099});
468	
469	    /**
470	     * Fixed region-to-timezone table mapping each known region to its IANA timezone name
471	     * (NSW -> Australia/Sydney, VIC -> Australia/Melbourne, QLD -> Australia/Brisbane). The single
472	     * source of truth for the timezone derivation read by {@link #getTimezone()}.
473	     */
474	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
475	        "NSW", "Australia/Sydney",
476	        "VIC", "Australia/Melbourne",
477	        "QLD", "Australia/Brisbane");
478	
479	    /**
480	     * The canonical region for {@code city} derived from the fixed city-to-region table
481	     * ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}), or {@code "UNKNOWN"} when the
482	     * city is not in the table. The single source of truth for the create-time postcode range check in
483	     * {@link org.springframework.samples.petclinic.rest.function.owner.ValidateOwnerPostcode}.
484	     */
485	    public static String regionOf(String city) {
486	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
487	    }
488	
489	    /**
490	     * The inclusive {low, high} four-digit postcode band for {@code region} (NSW 2000-2099,
491	     * VIC 3000-3099, QLD 4000-4099), or {@code null} when the region has no band. This is the single
492	     * source of truth for the bands, shared by {@link #regionOfPostcode(String) the postcode-to-region
493	     * lookup} (which feeds the customerCode's region, and hence the locality) and the create-time
494	     * postcode range check.
495	     */
496	    public static int[] postcodeRangeOf(String region) {
497	        return REGION_POSTCODES.get(region);
498	    }
499	
500	    /**
501	     * The canonical region whose postcode band contains {@code postcode} (NSW 2000-2099, VIC 3000-3099,
502	     * QLD 4000-4099), or {@code null} when {@code postcode} is absent, not four digits, or in no known
503	     * range.
504	     */
505	    public static String regionOfPostcode(String postcode) {
506	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
507	            return null;
508	        }
509	        int value = Integer.parseInt(postcode);
510	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
511	            int[] range = entry.getValue();
512	            if (value >= range[0] && value <= range[1]) {
513	                return entry.getKey();
514	            }
515	        }
516	        return null;
517	    }
518	
519	    /**
520	     * The owner's locality: the REGION segment of the {@link #getCustomerCode() customerCode}, which is
521	     * the region code derived from the postcode at creation (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099,
522	     * else {@code "UNKNOWN"}). The customer code is the single region-and-hash owner identity, so the
523	     * locality reads straight off it rather than re-deriving the region. {@code "UNKNOWN"} when no
524	     * customer code is assigned.
525	     */
526	    public String getLocality() {
527	        if (this.customerCode == null) {
528	            return "UNKNOWN";
529	        }
530	        int dash = this.customerCode.indexOf('-');
531	        return dash > 0 ? this.customerCode.substring(0, dash) : "UNKNOWN";
532	    }
533	
534	    /**
535	     * The owner's IANA timezone, derived from the {@link #getLocality() locality}/region via the fixed
536	     * region-to-timezone table (NSW -> Australia/Sydney, VIC -> Australia/Melbourne,
537	     * QLD -> Australia/Brisbane), or {@code null} (so the field is absent from the response) when the
538	     * locality maps to no known region.
539	     */
540	    public String getTimezone() {
541	        return REGION_TIMEZONE.get(getLocality());
542	    }
543	
544	    /**
545	     * The single Luhn check digit (0-9) computed over the digits contained in the
546	     * {@link #getCustomerCode() customerCode}: non-digit characters are ignored, each second digit from
547	     * the right is doubled (subtracting 9 when the double exceeds 9), the results are summed, and the
548	     * check digit is {@code (10 - sum % 10) % 10}. {@code 0} when no customer code is assigned.
549	     */
550	    public int getCheckDigit() {
551	        String code = this.customerCode;
552	        if (code == null) {
553	            return 0;
554	        }
555	        int sum = 0;
556	        boolean dbl = true;
557	        for (int i = code.length() - 1; i >= 0; i--) {
558	            char c = code.charAt(i);
559	            if (c < '0' || c > '9') {
560	                continue;
561	            }
562	            int d = c - '0';
563	            if (dbl) {
564	                d *= 2;
565	                if (d > 9) {
566	                    d -= 9;
567	                }
568	            }
569	            sum += d;
570	            dbl = !dbl;
571	        }
572	        return (10 - (sum % 10)) % 10;
573	    }
574	
575	    /**
576	     * The owner's preferred contact channel: {@code "EMAIL"} when an email is present, otherwise
577	     * {@code "PHONE"}.
578	     */
579	    public String getContactPreference() {
580	        boolean hasEmail = this.email != null && !this.email.isBlank();
581	        return hasEmail ? "EMAIL" : "PHONE";
582	    }
583	
584	    /**
585	     * The single canonical format of an owner's derived identity key:
586	     * {@code telephone + "|" + (email or empty) + "|" + (householdId or empty)}. The telephone and
587	     * household id are used as given (they are expected to already be canonical: E.164 and an assigned
588	     * household id); the email is lower-cased here and a null/blank email, telephone or household id
589	     * contributes an empty component. This is the only place the {@code "|"}-join lives; the stored-owner
590	     * {@link #getIdentityKey()} routes through here so the format cannot drift. The key is a descriptive,
591	     * returned field; create-time duplicate detection itself is keyed on the household alone (see
592	     * {@code CheckHouseholdUnique}).
593	     */
594	    public static String identityKey(String telephone, String email, String householdId) {
595	        String tel = (telephone == null) ? "" : telephone;
596	        String mail = (email == null || email.isBlank()) ? "" : email.toLowerCase(Locale.ROOT);
597	        String household = (householdId == null || householdId.isBlank()) ? "" : householdId;
598	        return tel + "|" + mail + "|" + household;
599	    }
600	
601	    /**
602	     * The owner's derived identity key, built from its stored canonical telephone (E.164), email and
603	     * household id via {@link #identityKey(String, String, String)}. A descriptive, returned value;
604	     * create-time duplicate detection is keyed on the household (see {@code CheckHouseholdUnique}).
605	     */
606	    public String getIdentityKey() {
607	        return identityKey(this.telephone, this.email, this.householdId);
608	    }
609	
610	    protected Set<Pet> getPetsInternal() {
611	        if (this.pets == null) {
612	            this.pets = new HashSet<>();
613	        }
614	        return this.pets;
615	    }
616	
617	    protected void setPetsInternal(Set<Pet> pets) {
618	        this.pets = pets;
619	    }
620	
621	    public List<Pet> getPets() {
622	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
623	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
624	        return Collections.unmodifiableList(sortedPets);
625	    }
626	
627	    public void setPets(List<Pet> pets) {
628	        this.pets = new HashSet<>(pets);
629	    }
630	
631	    public void addPet(Pet pet) {
632	        getPetsInternal().add(pet);
633	        pet.setOwner(this);
634	    }
635	
636	    /**
637	     * Return the Pet with the given name, or null if none found for this Owner.
638	     *
639	     * @param name to test
640	     * @return true if pet name is already in use
641	     */
642	    public Pet getPet(String name) {
643	        return getPet(name, false);
644	    }
645	
646	    /**
647	     * Return the Pet with the given name, or null if none found for this Owner.
648	     *
649	     * @param name to test
650	     * @return true if pet name is already in use
651	     */
652	    public Pet getPet(String name, boolean ignoreNew) {
653	        name = name.toLowerCase();
654	        for (Pet pet : getPetsInternal()) {
655	            if (!ignoreNew || !pet.isNew()) {
656	                String compName = pet.getName();
657	                compName = compName.toLowerCase();
658	                if (compName.equals(name)) {
659	                    return pet;
660	                }
661	            }
662	        }
663	        return null;
664	    }
665	
666	    public Pet getPet(Integer petId) {
667	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
668	    }
669	
670	    @Override
671	    public String toString() {
672	        return new ToStringCreator(this)
673	
674	            .append("id", this.getId())
675	            .append("new", this.isNew())
676	            .append("lastName", this.getLastName())
677	            .append("firstName", this.getFirstName())
678	            .append("address", this.address)
679	            .append("city", this.city)
680	            .append("telephone", this.telephone)
681	            .toString();
682	    }
683	}
