package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Ensures this owner's {@code possibleDuplicate} / {@code possibleDuplicateOf} response fields are set,
 * on both the create and read pipelines.
 *
 * <p>A possible duplicate was a soft near match: another owner sharing this owner's last name
 * (case-insensitively) and postcode. Now that the household is keyed on exactly (lastName, postcode)
 * (see {@link Household}), any such owner is in the <em>same household</em> and could only have been
 * created by declaring {@code sharesHousehold} to bypass the household duplicate block
 * ({@link CheckHouseholdUnique}) — a non-declared one is rejected with a 409. A declared household member
 * is not a suspected duplicate, so there is no longer any near match that should be flagged: the fields
 * are therefore always {@code false} / {@code null}. They are computed per request, not persisted, and
 * recomputed identically on each read.
 */
public class FlagPossibleDuplicate {

    public void service(@Val Owner owner) {
        owner.setPossibleDuplicate(false);
        owner.setPossibleDuplicateOf(null);
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Soft-deletes the owner: flags it {@code deleted} and saves, retaining the row rather than removing it.
 * The record is still readable via {@code GET /api/owners/{id}} (now reporting {@code deleted} true) but
 * is ignored by the create endpoint's duplicate/identity checks (see {@link CheckHouseholdUnique}).
 */
public class DeleteOwner {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        owner.setDeleted(true);
        ownerRepository.save(owner);
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.CityAtCapacityException;

/**
 * Rejects a new owner whose city already contains {@link #CAPACITY} or more owners, so the request is
 * answered with a 409 Conflict rather than exceeding the per-city capacity. Cities are compared in
 * their {@link OwnerCity#normalize normalized} form (whitespace collapsed, lower-cased), consistent
 * with the other create-time checks. Runs after {@link CheckHouseholdUnique} and before
 * {@link BuildOwner}.
 */
public class CheckCityCapacity {

    /** Maximum number of owners permitted per city. */
    static final int CAPACITY = 50;

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws CityAtCapacityException {
        String city = request.getCity();
        String normalizedCity = OwnerCity.normalize(city);
        int count = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (normalizedCity.equals(OwnerCity.normalize(existing.getCity()))) {
                count++;
            }
        }
        if (count >= CAPACITY) {
            throw new CityAtCapacityException(city, CAPACITY);
        }
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Single source of truth for household identity. A household groups owners that share the same last
 * name and the same postcode, with the last name compared case-insensitively and with surrounding and
 * internal whitespace collapsed (so "Smith" / " smith " belong together).
 *
 * <p>The {@link #id(String, String)} derived from that normalized (lastName, postcode) pair is
 * deterministic: the same last name and postcode always map to the same value, so every owner at the
 * same household receives an identical {@code householdId} automatically — it is no longer something an
 * owner "joins" via {@code sharesHousehold}. The household is therefore the basis for duplicate
 * detection ({@link CheckHouseholdUnique}): two owners belong to the same household exactly when their
 * ids are equal.
 */
final class Household {

    private Household() {
    }

    /** Lower-case (locale-independent) with leading/trailing and repeated internal whitespace collapsed. */
    private static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }

    /**
     * The canonical household key for a (lastName, postcode) pair — the single definition of household
     * membership: {@code normalizedLastName + "|" + postcode}. Two owners belong to the same household
     * exactly when their keys are equal; {@link #id} hashes this same key, so the duplicate check and the
     * assigned id can never diverge. The last name is normalized (whitespace collapsed, lower-cased); the
     * postcode is trimmed and used as given (a {@code null} or blank postcode contributes an empty
     * component).
     */
    static String key(String lastName, String postcode) {
        String pc = (postcode == null) ? "" : postcode.trim();
        return normalize(lastName) + "|" + pc;
    }

    /**
     * All existing owners that belong to the household of the given last name and postcode — those whose
     * own (recomputed) {@link #id household id} equals this household's. The single definition of
     * "collect the members of a household", shared by the callers that count members and that cap a new
     * member's level; soft-deleted owners are included (callers that must exclude them filter the result).
     */
    static List<Owner> membersOf(String lastName, String postcode, OwnerRepository repository) {
        String householdId = id(lastName, postcode);
        List<Owner> members = new ArrayList<>();
        for (Owner existing : repository.findAll()) {
            if (householdId.equals(id(existing.getLastName(), existing.getPostcode()))) {
                members.add(existing);
            }
        }
        return members;
    }

    /**
     * Deterministic household identifier for the given last name and postcode: {@code "H-"} followed by
     * the first 12 hex characters of the SHA-256 of the {@link #key household key}.
     */
    static String id(String lastName, String postcode) {
        String key = key(lastName, postcode);
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder("H-");
            for (int i = 0; i < 6; i++) {
                sb.append(String.format("%02x", digest[i]));
            }
            return sb.toString();
        }
        catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 not available", e);
        }
    }
}

